'use strict'
const root=document.querySelector('#app'),message=document.querySelector('#message')
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const label={new:'Заявка',assembling:'Сборка',ready:'Можно забирать',received:'Получен',cancelled:'Отменён'}
let me
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify({...data,csrf:me?.csrf}):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error||'Операция недоступна');return d}
const nav=()=>`<nav><a class="button secondary" href="/shop">Мой магазин</a>${me.adminUnits.length?'<a class="button secondary" href="/admin">Заказы и остатки</a><a class="button secondary" href="/access">Доступы и приглашения</a><a class="button secondary" href="/mailbox">Тестовый почтовый ящик</a>':''}${me.isSuper?'<a class="button secondary" href="/data">Хранение и очистка</a>':''}<button id="logout" class="quiet">Выйти</button></nav>`
function frame(content){root.innerHTML=`<span class="eyebrow">Внутренний контур · проверяемая архитектура</span><h1>Uzum Merch Shop</h1><p class="muted">${esc(me.name)} · ${me.method==='oidc'?'тестовый Keycloak':me.method==='email'?'личная почта · Welcome pack':'персональное приглашение'}</p>${nav()}${content}`;document.querySelector('#logout').onclick=async()=>{await fetch('/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:me.csrf})});location.assign('/')}}
async function shop(){
 if(!me.campaign)return frame('<section class="card"><h2>Вы вошли как организатор</h2><p>Ваша служебная учётная запись не является участником раздачи. Откройте заказы, остатки или тестовый почтовый ящик.</p></section>')
 const [variants,orders]=await Promise.all([api('/api/catalog'),api('/api/orders')])
 const names=[...new Set(variants.map(v=>v.product))]
 frame(`<div class="grid"><section><h2>${me.scope==='welcome'?'Welcome pack':'Каталог'} · ${esc(me.unit)}</h2><form id="order-form"><div class="products">${names.map((name,i)=>{const vs=variants.filter(v=>v.product===name);return`<article class="product"><img alt="${esc(name)}" src="/files/${esc(vs[0].image_name)}"><div class="body"><label><input type="checkbox" name="item" value="${i}">${esc(name)}</label><label>Размер / цвет<select data-product="${i}">${vs.map(v=>`<option value="${v.id}" ${v.available<1?'disabled':''}>${esc(v.size)} · ${esc(v.color)} · ${v.available} шт.</option>`).join('')}</select></label></div></article>`}).join('')}</div><section class="card"><h2>Очное получение</h2><p>Пилотная раздача без телефона, адреса, отдела и юрлица. Дату и место сообщит организатор.</p><div class="note">${esc(me.name)}${me.email?' · '+esc(me.email):''}. Кадровые данные не вводятся в заказ и не копируются в него.</div><p id="selection"></p><button ${orders.some(o=>o.status!=='cancelled')?'disabled':''}>Оформить заказ</button></section></form></section><section><h2>Мои заказы</h2>${orders.map(o=>`<article class="card"><span class="pill">${label[o.status]}</span><h3>Заказ ${o.id.slice(0,8)}</h3><ul>${o.items.map(i=>`<li>${esc(i.product)} · ${esc(i.size)} · ${esc(i.color)}</li>`).join('')}</ul>${!['received','cancelled'].includes(o.status)?`<img class="qr" alt="QR-код получения" src="/api/orders/${o.id}/receipt.svg"><p><a href="/api/orders/${o.id}/receipt.svg" download="merch-receipt.svg">Скачать QR</a></p><button class="secondary cancel" data-id="${o.id}">Отменить заказ</button>`:'<p>Повторного списания по этому коду не будет.</p>'}</article>`).join('')||'<p class="muted">Заказов пока нет.</p>'}</section></div>`)
 const form=document.querySelector('#order-form'),requestKey=crypto.randomUUID()
 form.onchange=()=>{document.querySelector('#selection').textContent=[...form.querySelectorAll('[name=item]:checked')].map(x=>names[Number(x.value)]).join(', ')}
 form.onsubmit=async e=>{e.preventDefault();try{const items=[...form.querySelectorAll('[name=item]:checked')].map(x=>form.querySelector(`[data-product="${x.value}"]`).value);await api('/api/orders',{items,requestKey});message.textContent='Заказ оформлен, товар зарезервирован.';await shop()}catch(error){message.textContent=error.message}}
 document.querySelectorAll('.cancel').forEach(b=>b.onclick=async()=>{try{await api('/api/orders/'+b.dataset.id+'/cancel',{});await shop()}catch(e){message.textContent=e.message}})
}
async function admin(){
 const [orders,stocks,analytics]=await Promise.all([api('/api/admin/orders'),api('/api/admin/stocks'),api('/api/admin/analytics')])
 frame(`<section class="card"><h2>Выдача по QR</h2><p>Подключите 2D-сканер, вводящий код как клавиатура, или вставьте тестовый код. Камера в этом новом стенде пока не подключена.</p><form id="issue"><label>Код получения<input name="token" required autocomplete="off"></label><button>Выдать подготовленный заказ</button></form></section><section class="card"><h2>Заказы</h2>${orders.map(o=>`<article class="order"><span class="pill">${esc(o.unit)} · ${label[o.status]}</span><h3>${esc(o.full_name)} · ${o.id.slice(0,8)}</h3><p>${o.items.map(i=>`${esc(i.product)} / ${esc(i.size)}`).join(', ')}</p>${o.status==='new'?`<button class="next" data-id="${o.id}" data-status="assembling">Начать сборку</button>`:o.status==='assembling'?`<button class="next" data-id="${o.id}" data-status="ready">Можно забирать</button>`:''}</article>`).join('')||'<p>Нет заказов.</p>'}</section><h2>Остатки и предупреждения</h2><div class="stock">${stocks.map(v=>`<form class="card stock-form" data-id="${v.id}"><span class="pill">${esc(v.unit)}</span><h3>${esc(v.product)} · ${esc(v.size)}</h3><p>На складе ${v.total} · Зарезервировано ${v.reserved} · Доступно ${v.available}</p>${v.available<=v.threshold?'<p class="warning">Мало осталось</p>':''}<label>Изменить количество на<input name="delta" type="number" value="0" required></label><label>Порог предупреждения<input name="threshold" type="number" value="${v.threshold}" min="0" required></label><label><input name="active" type="checkbox" ${v.active?'checked':''}>Товар доступен</label><button>Сохранить</button></form>`).join('')}</div><section class="card"><h2>Количество выданного</h2><a href="/api/admin/analytics?format=csv">Экспорт CSV без ФИО и контактов</a><div class="overflow"><table><tr><th>Магазин</th><th>Товар</th><th>Размер</th><th>Выдано</th></tr>${analytics.map(a=>`<tr><td>${esc(a.unit)}</td><td>${esc(a.product)}</td><td>${esc(a.size)}</td><td>${a.issued}</td></tr>`).join('')}</table></div></section>`)
 document.querySelector('#issue').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/admin/issue',{token:e.target.token.value.trim()});message.textContent=r.already?'Уже выдан — повторного списания нет.':'Заказ выдан. Остатки обновлены.';await admin()}catch(error){message.textContent=error.message}}
 document.querySelectorAll('.next').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/orders/'+b.dataset.id+'/status',{status:b.dataset.status});await admin()}catch(e){message.textContent=e.message}})
 document.querySelectorAll('.stock-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/stocks/'+f.dataset.id,{delta:Number(f.delta.value),threshold:Number(f.threshold.value),active:f.active.checked});await admin()}catch(error){message.textContent=error.message}})
}
function welcomePanel(people,campaigns){return `<section class="card"><h2>Новички без портала · Welcome pack</h2><p>Укажите личную почту. Письмо даст доступ только к Welcome pack. После выдачи заказ закрывает доступ автоматически. В стенде письмо видно в тестовом почтовом ящике, реальной отправки нет.</p><form id="welcome-invite"><label>ФИО<input name="fullName" required maxlength="250"></label><label>Личная почта<input name="email" type="email" required placeholder="newcomer@example.invalid"></label><label>Магазин / раздача<select name="campaignId">${campaigns.filter(c=>c.status==='open').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Срок доступа, дней<input name="validDays" type="number" min="1" max="90" value="14" required></label><button ${!campaigns.some(c=>c.status==='open')?'disabled':''}>Пригласить в Welcome pack</button></form>${people.map(p=>`<article class="order"><b>${esc(p.full_name)}</b><p>${esc(p.email)} · ${esc(p.unit)}</p><p>${p.welcome_received_at?'Получил мерч — доступ закрыт':!p.active?'Доступ отозван':new Date(p.access_expires_at)<=new Date()?'Срок приглашения истёк':p.email_verified_at?'Почта подтверждена':'Ожидает подтверждения почты'}</p>${p.active&&!p.welcome_received_at?`<button type="button" class="revoke-welcome secondary" data-id="${p.id}">Отозвать доступ</button>`:''}</article>`).join('')}<p><a href="/email-login">Страница повторного входа по личной почте</a></p></section>`}
function wireWelcome(){
 const f=document.querySelector('#welcome-invite')
 f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('button');button.disabled=true;try{await api('/api/admin/welcome-email',{action:'invite',fullName:f.fullName.value,email:f.email.value,campaignId:f.campaignId.value,validDays:Number(f.validDays.value)});message.textContent='Тестовое приглашение создано. Ссылка находится в тестовом почтовом ящике.';await access()}catch(e){message.textContent=e.message;button.disabled=false}}
 document.querySelectorAll('.revoke-welcome').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/welcome-email',{action:'revoke',employeeId:b.dataset.id});await access()}catch(e){message.textContent=e.message}})
}
async function access(){
 const [d,welcome]=await Promise.all([api('/api/admin/portal'),api('/api/admin/welcome-email')])
 const titles={person:'Отдельный сотрудник',legal_entity:'Юрлицо',group:'Группа портала'}
 const values={person:d.people.map(p=>({code:p.subject,name:p.name+' · '+p.email,active:p.active})),legal_entity:d.legalEntities,group:d.groups}
 const title=r=>(values[r.kind].find(x=>x.code===r.value)?.name||r.value)
 frame(`${welcomePanel(welcome,d.campaigns)}<section class="card"><h2>Доступ через портал</h2><p class="note">Только вымышленные сотрудники и тестовый Keycloak. Настоящий портал не подключён. Перечень ниже — мок каталога, а не скопированный HR-реестр.</p><p>Выберите отдельных людей, целое юрлицо или группу. Новому участнику не нужна предварительная запись в реестре: она создаётся при разрешённом входе. Административные права эти правила не выдают.</p><form id="portal-rule"><label>Раздача<select name="campaignId">${d.campaigns.filter(c=>c.status==='open').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Кого выбрать<select name="kind">${Object.entries(titles).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Поиск сотрудника<input name="search" placeholder="ФИО или рабочий email"></label><label>Значение<select name="value"></select></label><label>Решение<select name="effect"><option value="allow">Разрешить</option><option value="deny">Исключить из доступа</option></select></label><label>Открыть только<select name="scope"><option value="catalog">Основной каталог</option><option value="welcome">Welcome pack</option></select></label><button ${!d.campaigns.some(c=>c.status==='open')?'disabled':''}>Сохранить правило</button></form></section><section class="card"><h2>Действующие настройки</h2><p>Исключение сильнее разрешения. Если разрешения ведут в разные магазины или одновременно в каталог и Welcome pack, вход закрыт до исправления конфликта. Существующий заказ и закрепление за магазином автоматически не переносятся.</p>${d.rules.map(r=>`<article class="order"><b>${esc(r.campaign_name)} · ${r.scope==='welcome'?'Welcome pack':'Каталог'}</b><p>${esc(titles[r.kind])}: ${esc(title(r))}</p><p>${r.effect==='deny'?'Исключение':'Разрешение'} · ${r.enabled?'Включено':'Выключено'}</p><button class="toggle secondary" data-id="${r.id}" data-enabled="${!r.enabled}">${r.enabled?'Выключить':'Включить'}</button></article>`).join('')||'<p>Правил пока нет. Доступ по умолчанию закрыт.</p>'}<p class="muted">Правила перепроверяются при каждом обращении участника. Изменение юрлица, группы или занятости на самом портале будет видно при новом входе, не позднее окончания 15-минутной сессии. Старые явно заданные разрешения реестра и служебные аккаунты организаторов сохраняются отдельно.</p></section>`)
 wireWelcome();const f=document.querySelector('#portal-rule')
 const refresh=()=>{const q=f.search.value.trim().toLocaleLowerCase();f.value.innerHTML=values[f.kind.value].filter(x=>f.kind.value!=='person'||x.name.toLocaleLowerCase().includes(q)).map(x=>`<option value="${esc(x.code)}" ${x.active===false?'disabled':''}>${esc(x.name)}${x.active===false?' · неактивен':''}</option>`).join('');f.search.closest('label').hidden=f.kind.value!=='person'}
 f.kind.onchange=refresh;f.search.oninput=refresh;refresh()
 f.onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/portal/rules',{campaignId:f.campaignId.value,kind:f.kind.value,value:f.value.value,effect:f.effect.value,scope:f.scope.value});message.textContent='Правило сохранено. Приглашения по почте не отправлялись.';await access()}catch(e){message.textContent=e.message}}
 document.querySelectorAll('.toggle').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/portal/toggle',{id:b.dataset.id,enabled:b.dataset.enabled==='true'});await access()}catch(e){message.textContent=e.message}})
}
async function mailbox(){const mails=await api('/api/admin/mailbox');frame(`<section class="card"><h2>Тестовый почтовый ящик</h2><p>Реальных писем нет. Содержимое хранится зашифрованным в тестовой БД и очищается вместе с участниками раздачи.</p>${mails.map(m=>`<article class="order"><h3>${esc(m.subject)}</h3><p>${esc(m.to)}</p><p>${esc(m.body)}</p><a href="${esc(m.url)}" target="_blank" rel="noreferrer">Открыть тестовую ссылку</a></article>`).join('')}</section>`)}
async function data(){const d=await api('/api/admin/data');frame(`<section class="card"><h2>Где хранятся данные</h2><div class="overflow"><table><tr><th>Компонент</th><th>Место</th></tr>${Object.entries(d.storage).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</table></div><h3>Персональные поля приложения</h3><ul>${d.fields.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="note">Сроки ${d.policy.profile_days} дней после закрытия раздачи и ${d.policy.log_days} дней для прикладных событий — тестовые предложения, не согласованный регламент. Очистку выполняет отдельный worker каждые 5 секунд.</p><p>Профилей участников: ${d.profiles}. Заказов: ${d.orders}. Приглашений: ${d.invitations}. Писем: ${d.outbox}.</p><p>Служебные аккаунты организаторов имеют отдельную цель и не удаляются с участниками раздачи.</p></section><section class="card"><h2>Раздачи</h2>${d.campaigns.map(c=>`<article class="order"><b>${esc(c.name)}</b><p>${c.status==='open'?'Открыта':'Закрыта'}${c.purged_at?' · персональные данные очищены':''}</p>${c.status==='open'?`<button class="close" data-id="${c.id}">Закрыть раздачу</button>`:''}</article>`).join('')}</section><section class="card"><h2>Резервные копии и источник авторизации</h2><p>Очистка рабочей БД не удаляет старые резервные копии автоматически. Предусмотрены отдельные зашифрованные копии и журнал удалений для повторной очистки при восстановлении.</p><p>Данные тестового Keycloak принадлежат отдельному источнику авторизации. При очистке раздачи они не удаляются; в компании их жизненный цикл определяется владельцем корпоративного провайдера.</p></section>`);document.querySelectorAll('.close').forEach(b=>b.onclick=async()=>{if(!confirm('Закрыть раздачу, отменить незавершённые заказы и закрыть доступ участников?'))return;try{await api('/api/admin/campaigns/'+b.dataset.id+'/close',{});await data()}catch(e){message.textContent=e.message}})}
(async()=>{try{me=await api('/api/me');if(me.method==='email')setInterval(async()=>{try{const r=await fetch('/api/me');if(r.status===401)location.assign('/email-login')}catch{}},10000);await(location.pathname==='/access'?access():location.pathname==='/admin'?admin():location.pathname==='/mailbox'?mailbox():['/data','/review'].includes(location.pathname)?data():shop())}catch(error){if(!me){root.innerHTML='<section class="card portal"><h1>Тестовый внутренний мерчшоп</h1><p>Реальный серверный путь с собственной PostgreSQL и отдельным тестовым Keycloak. Данные вымышлены.</p><a class="button" href="/auth/login">Войти через тестовый Keycloak</a><p><a href="/email-login">Welcome pack: войти по личной почте</a></p><p class="muted">alice — покупатель E-com; boris — Welcome pack; organizer — супер администратор; fintech-admin — только Fintech. Пароль находится в локальном файле .local/accounts.json.</p><p>Персональную гостевую ссылку организатор получает в тестовом почтовом ящике. Код: TEST-GUEST-001.</p></section>'}else message.textContent=error.message}})()
